  "offline.noSignal": "சிக்னல் இல்லை. நீங்கள் தொடரலாம்: உங்கள் பதில்கள் இந்த ஃபோனில் சேமிக்கப்பட்டுள்ளன, சிக்னல் வந்ததும் அனுப்பப்படும்.",
  "offline.noSignalWaiting": "சிக்னல் இல்லை. உங்கள் பதில்கள் இந்த ஃபோனில் சேமிக்கப்பட்டுள்ளன, சிக்னல் வந்ததும் அனுப்பப்படும். அனுப்பக் காத்திருப்பவை: {count}",
  "offline.sending": "அனுப்பப்படுகிறது… இன்னும் அனுப்ப வேண்டியவை: {count}",
  "offline.retrying": "இன்னும் அனுப்ப முடியவில்லை. தானாகவே மீண்டும் முயற்சிக்கிறது. அனுப்பக் காத்திருப்பவை: {count}",
  "offline.allSent": "அனைத்தும் அனுப்பப்பட்டது",
  "offline.tryNow": "இப்போது முயற்சிக்கவும்",
  "offline.itemSaved": "இந்த ஃபோனில் சேமிக்கப்பட்டது. இன்னும் அனுப்பப்படவில்லை.",
  "offline.runUnsent": "இந்த ஃபோனில் சேமிக்கப்பட்டு, இன்னும் அனுப்பப்படாதவை: {count}",
  "offline.submitWaiting": "இந்த ஃபோனில் சமர்ப்பிக்கப்பட்டது, ஆனால் இன்னும் அனுப்பப்படவில்லை. சிக்னல் வந்ததும் அனுப்பப்படும்.",
  "offline.submitSaved": "இந்த ஃபோனில் சேமிக்கப்பட்டது. சிக்னல் வந்ததும் அனுப்பப்படும்.",
  "offline.notOnPhone": "சிக்னல் இல்லை, இந்த செக்லிஸ்ட் இன்னும் இந்த ஃபோனில் சேமிக்கப்படவில்லை. சிக்னல் இருக்கும்போது ஒரு முறை திறக்கவும்.",
  "offline.saveFailed": "இதை ஃபோனில் சேமிக்க முடியவில்லை. ஃபோனில் கொஞ்சம் இடத்தைக் காலி செய்து மீண்டும் முயற்சிக்கவும்.",
  "offline.someone": "வேறொருவர்",
  "offline.thisChecklist": "இந்த செக்லிஸ்ட்",
  "offline.conflictSubmitted": "உங்கள் பதில்கள் அனுப்பப்படும் முன்பே {name} {title} சமர்ப்பித்துவிட்டார். இந்த ஃபோனிலிருந்து சேர்க்கப்படாத பதில்கள்: {count}. செக்லிஸ்ட் இப்போது சமர்ப்பிக்கப்பட்டதையே காட்டுகிறது.",
  "offline.conflictSubmittedNone": "{name} ஏற்கனவே {title} சமர்ப்பித்துவிட்டார், அதனால் இந்த ஃபோனிலிருந்து மீண்டும் சமர்ப்பிக்கப்படவில்லை. செக்லிஸ்ட் சமர்ப்பிக்கப்பட்டதையே காட்டுகிறது.",
  "offline.conflictClosed": "{title}: இது முந்தைய நாளுக்கானது, மூடப்பட்டுவிட்டது. இந்த ஃபோனிலிருந்து சேர்க்க முடியாத பதில்கள்: {count}.",
  "offline.rejected": "{title}: சில பதில்களை சர்வர் ஏற்கவில்லை. சேமிக்கப்படாதவை: {count}. செக்லிஸ்டைத் திறந்து அந்த ஐட்டங்களை மீண்டும் செய்யவும்.",
  "offline.submitRejected": "{title} சமர்ப்பிக்க முடியவில்லை. அதைத் திறந்து, ஒவ்வொரு ஐட்டமும் முடிந்ததா என்று பார்த்து, மீண்டும் சமர்ப்பிக்கவும்.",
