  "plan.help": "ஒவ்வொரு பில்லிங் காலத்துக்கும் ஒரே விலையில் ECCS-இன் வழக்கமான விசிட்கள்.",
  "plan.ownerOnly": "பிளானைத் தேர்ந்தெடுக்க, மாற்ற அல்லது ரத்து செய்ய ஓனரால் மட்டுமே முடியும்.",
  "plan.notForYou": "பிளானை ஓனரும் மேனேஜரும் கவனித்துக்கொள்கிறார்கள்.",
  "plan.choose": "ஒரு பிளானைத் தேர்ந்தெடுக்கவும்",
  "plan.chooseHelp": "ஒவ்வொரு பிளானிலும் சில வழக்கமான விசிட்கள் உள்ளன. ECCS அவற்றை உங்கள் டைரியில் தானாகவே சேர்க்கும்.",
  "plan.noneOffered": "இப்போது பிளான்கள் எதுவும் இல்லை. ECCS-க்கு ஃபோன் செய்யுங்கள்.",
