  "plan.billed.ANNUAL": "வருடத்துக்கு ஒரு முறை முன்கூட்டியே இன்வாய்ஸ் வரும்",
  "plan.subscribeTo": "{plan} பிளானில் சேரவும்",
  "plan.subscribeConfirm": "{plan} பிளானில் சேரவா?\n\nநீங்கள் GST உட்பட {price} செலுத்துவீர்கள். முதல் காலத்துக்கு ECCS இன்வாய்ஸ் கொடுக்கும்: {from} முதல் {until} வரை.\n\nஉங்கள் முதல் விசிட்கள் {date} அன்றைக்கு உங்கள் டைரியில் சேர்க்கப்படும். நேரத்தை ECCS உறுதிப்படுத்தும்.\n\nபிளான் ஒவ்வொரு காலத்துக்கும் தானாகவே ரினியூ ஆகும். இந்த ஸ்கிரீனிலேயே எப்போது வேண்டுமானாலும் ரத்து செய்யலாம்.",
  "plan.subscribeYes": "பிளானில் சேரவும்",
  "plan.notNow": "இப்போது வேண்டாம்",
  "plan.subscribed": "நீங்கள் இப்போது {plan} பிளானில் இருக்கிறீர்கள்",
