  "plan.state.PAUSED": "ECCS நிறுத்தி வைத்துள்ளது",
  "plan.state.ENDING": "{date} அன்று முடியும்",
  "plan.state.CHANGING": "{date} அன்று {plan} ஆக மாறும்",
  "plan.pausedHelp": "ECCS இந்த பிளானை நிறுத்தி வைத்துள்ளது. நிறுத்தி வைத்திருக்கும் வரை புதிய விசிட்கள் சேர்க்கப்படாது, பிளான் ரினியூ ஆகாது. மீண்டும் தொடங்க ECCS-க்கு ஃபோன் செய்யுங்கள்.",
  "plan.endingHelp": "உங்கள் விசிட்கள் {date} வரை தொடரும். அதன் பிறகு பிளான் ரினியூ ஆகாது, புதிய இன்வாய்ஸ் எதுவும் வராது.",
  "plan.changingHelp": "அதுவரை உங்கள் பிளான் {current} ஆகவே இருக்கும். {date} முதல் நீங்கள் {next} பிளானில் இருப்பீர்கள்: {price}, GST உட்பட.",
  "plan.edited": "ECCS இந்த பிளானை மாற்றியுள்ளது. {date} முதல் விலை {price}, GST உட்பட.",
