  "plan.nextInvoicePaused": "பிளான் நிறுத்தி வைத்திருக்கும் வரை எதுவும் இல்லை.",
  "plan.change": "பிளானை மாற்றவும்",
  "plan.changeTitle": "வேறு பிளானுக்கு மாறவும்",
  "plan.changeHelp": "மாற்றம் உங்கள் அடுத்த காலத்திலிருந்து, அதாவது {date} முதல் தொடங்கும். அதுவரை உங்கள் பிளான் இப்போது இருப்பது போலவே இருக்கும்; இன்று எந்தக் கட்டணமும் இல்லை.",
  "plan.changeTo": "{plan} பிளானுக்கு மாறவும்",
  "plan.changeConfirm": "{date} அன்று {plan} பிளானுக்கு மாறவா?\n\nஅதுவரை உங்கள் பிளான் {current} ஆகவே இருக்கும்; அதற்கு ஏற்கனவே இன்வாய்ஸ் கொடுக்கப்பட்டுவிட்டது.\n\n{date} முதல் நீங்கள் GST உட்பட {price} செலுத்துவீர்கள், {plan} பிளானின் சர்வீஸ்கள் கிடைக்கும். {plan} பிளானில் இல்லாத சர்வீஸ்கள் அன்றே நின்றுவிடும்.\n\n{date} வரை இந்த மாற்றத்தைத் திரும்பப் பெறலாம்.",
  "plan.changeYes": "பிளானை மாற்றவும்",
  "plan.changeNo": "{plan} பிளானையே வைத்திரு",
  "plan.changeSaved": "நீங்கள் {date} அன்று {plan} பிளானுக்கு மாறுவீர்கள்",
  "plan.undoChange": "{plan} பிளானிலேயே இருக்கவும்",
  "plan.changeUndone": "நீங்கள் {plan} பிளானிலேயே தொடர்வீர்கள்",
  "plan.noOther": "இப்போது மாறுவதற்கு வேறு பிளான் எதுவும் இல்லை.",
  "plan.closeChange": "பிளான்களின் பட்டியலை மூடவும்",
  "plan.cancel": "பிளானை ரத்து செய்",
  "plan.cancelConfirm": "{plan} பிளானை ரத்து செய்யவா?\n\nஉங்கள் விசிட்கள் {date} வரை, அதாவது ஏற்கனவே இன்வாய்ஸ் கொடுக்கப்பட்ட காலத்தின் இறுதி வரை தொடரும்.\n\n{date} அன்றைக்குப் பிறகு பிளான் ரினியூ ஆகாது, புதிய இன்வாய்ஸ் எதுவும் வராது, அந்த நாளுக்குப் பிறகு திட்டமிட்ட விசிட்கள் உங்கள் டைரியிலிருந்து நீக்கப்படும்.\n\n{date} வரை இதைத் திரும்பப் பெறலாம்.",
  "plan.cancelConfirmNow": "{plan} பிளானை ரத்து செய்யவா?\n\nஇது இன்றே முடிந்துவிடும். இன்னும் தொடங்காத இதன் விசிட்கள் உங்கள் டைரியிலிருந்து நீக்கப்படும், புதிய இன்வாய்ஸ் எதுவும் வராது.\n\nஇதைத் திரும்பப் பெற முடியாது, ஆனால் நீங்கள் மீண்டும் பிளானில் சேரலாம்.",
  "plan.cancelYes": "பிளானை ரத்து செய்",
  "plan.keep": "என் பிளானைத் தொடரவும்",
