  "bill.sampleTitle": "மாதிரி பேமென்ட். பணம் எதுவும் எடுக்கப்படாது.",
  "bill.sampleBody": "உண்மையான பேமென்ட்கள் இன்னும் தொடங்கப்படவில்லை. எந்தக் கணக்கிலிருந்தும் எதுவும் எடுக்கப்படாது. பணம் செலுத்துவது எப்படி இருக்கும் என்பதை மட்டுமே இந்த ஸ்கிரீன் காட்டுகிறது.",
