  "push.channel.remindersHelp": "நேரம் கடந்த செக்லிஸ்ட்கள், காலாவதியாகப் போகும் லைசென்ஸ்கள், வரவிருக்கும் விசிட்கள்",
  "push.ask.title": "உடனே தெரிவிக்கவா?",
  "push.ask.body": "நீங்கள் கவனிக்க வேண்டியது ஏதாவது இருக்கும்போது ECCS இந்த ஃபோனில் அறிவிப்பைக் காட்டும்: விசிட் முடிந்தது, ECCS பதில் அளித்தது, செக்லிஸ்ட் நேரம் கடந்துவிட்டது, லைசென்ஸ் காலாவதியாகப் போகிறது. பார்ப்பதற்காக அடிக்கடி ஆப்பைத் திறக்க வேண்டியதில்லை.",
  "push.ask.shared": "பலர் பயன்படுத்தும் ஃபோனில், லாகின் செய்திருப்பவருக்கு மட்டுமே அவை வரும். லாக் செய்த பிறகு எதுவும் காட்டப்படாது.",
  "push.ask.yes": "அறிவிப்புகளை ஆன் செய்யவும்",
  "push.ask.notNow": "இப்போது வேண்டாம்",
  "push.status.on": "இந்த ஃபோனில் அறிவிப்புகள் ஆன் ஆக உள்ளன.",
  "push.status.off": "இந்த ஃபோனில் அறிவிப்புகள் ஆஃப் ஆக உள்ளன. புதியவை ஆப்பைத் திறக்கும்போது மட்டுமே தெரியும்.",
  "push.status.blocked": "இந்த ஃபோனின் செட்டிங்ஸில் ECCS அறிவிப்புகள் தடுக்கப்பட்டுள்ளன. உடனே தெரிந்துகொள்ள அங்கே அவற்றை அனுமதிக்கவும்.",
  "push.status.failed": "இந்த ஃபோனில் அறிவிப்புகளை அமைக்க முடியவில்லை. இன்டர்நெட் இணைப்பைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.",
  "push.status.serverOff": "இந்த ஃபோனில் அறிவிப்புகள் ஆன் ஆக உள்ளன, ஆனால் ECCS இன்னும் ஃபோன்களுக்கு அவற்றை அனுப்பத் தொடங்கவில்லை.",
  "push.status.unavailable": "ஆப்பின் இந்தப் பதிப்பால் ஃபோனில் அறிவிப்புகளைக் காட்ட முடியாது. புதியவை ஆப்பைத் திறக்கும்போது தெரியும்.",
  "push.openSettings": "ஃபோன் செட்டிங்ஸைத் திறக்கவும்",
  "push.turnedOn": "அறிவிப்புகள் ஆன் செய்யப்பட்டன",
