  "push.test.body": "இந்த ஃபோனில் ECCS அறிவிப்புகள் வேலை செய்கின்றன.",

  "place.ask.title": "ஆதார போட்டோக்களுடன் இடத்தையும் சேர்க்கவா?",
  "place.ask.body": "நீங்கள் ஆதார போட்டோ எடுக்கும்போது, இந்த ஃபோன் எங்கே இருக்கிறது என்பதை ஆப் குறித்துக்கொள்ளும். போட்டோ இந்தக் கிச்சனில்தான் எடுக்கப்பட்டது என்பதை அது காட்டும்.",
