  "visit.place.title": "இந்தக் கிச்சனின் லொகேஷன் இன்னும் சேமிக்கப்படவில்லை",
  "visit.place.help": "கிச்சனில் இருக்கும்போது ஒரு முறை சேமிக்கவும். ஆதார போட்டோக்கள் இங்கேதான் எடுக்கப்பட்டனவா என்று சரிபார்க்க இது பயன்படும். சிக்னல் தேவை.",
