  "public.services.none": "கடந்த 12 மாதங்களில் ECCS சுத்தம் அல்லது பூச்சிக் கட்டுப்பாடு சர்வீஸ் எதுவும் இல்லை.",
  "public.services.cert": "ECCS சர்டிஃபிகேட் {number}, {date} வரை செல்லும்",
  "public.photos.heading": "கிச்சனின் போட்டோக்கள்",
  "public.photos.takenOn": "{date} அன்று எடுக்கப்பட்டது",
  "public.photo.GRILL": "கிரில்",
  "public.photo.HOOD": "ஹூட் மற்றும் எக்ஸாஸ்ட்",
  "public.photo.COLD_STORAGE": "குளிர் சேமிப்பு",
  "public.photo.PREP_AREA": "உணவு தயாரிக்கும் இடம்",
  "public.photo.FLOOR_DRAINS": "தரை மற்றும் வடிகால்கள்",
  "public.photo.WASH_AREA": "கழுவும் இடம்",
  "public.how.2": "ஒவ்வொரு அம்சமும் பூர்த்தியானதா இல்லையா என்று குறிக்கப்படும். பெறக்கூடிய மொத்த மதிப்பெண்களில் பெற்ற மதிப்பெண்களை 100-இல் ஒரு எண்ணாகக் காட்டுவதே ஸ்கோர். கடுமையான ஆபத்து தொடர்பான அம்சங்கள் இரு மடங்காகக் கணக்கிடப்படும்.",
  "public.how.3": "கிரேடு A+ என்றால் {aPlus} அல்லது அதற்கு மேல், A என்றால் {a} அல்லது அதற்கு மேல், B என்றால் {b} அல்லது அதற்கு மேல். {b}-க்குக் கீழ் இருந்தால், அல்லது கடுமையான ஆபத்து தொடர்பான ஏதாவது ஒரு அம்சம் பூர்த்தியாகாவிட்டால், கிரேடு வழங்கப்படாது.",
  "public.how.4": "ஒவ்வொரு ரிப்போர்ட்டும் இங்கே தெரிவதற்கு முன் ECCS அலுவலகம் அதை அங்கீகரிக்கிறது. ஒரு முடிவு {days} நாட்கள் காட்டப்படும்; பிறகு அடுத்த இன்ஸ்பெக்ஷன் வரை இந்தப் பக்கத்திலிருந்து நீக்கப்படும்.",
  "public.not.heading": "இதில் அடங்காதவை",
  "public.not.2": "உணவின் சுவை அல்லது தரம், சர்வீஸ் அல்லது சாப்பிடும் இடம் பற்றி இது எதுவும் சொல்லவில்லை.",
  "public.not.3": "உணவு உங்களுக்குப் பாதுகாப்பானது என்பதற்கு இது உறுதி அல்ல. உங்களுக்கு அலர்ஜி இருந்தால், ஸ்டாஃபிடம் கேளுங்கள்.",
  "public.gov.heading": "இது அரசு ரேட்டிங் அல்ல",
  "public.gov.check": "ஒவ்வொரு ரெஸ்டாரன்ட்டும் தன் FSSAI லைசென்ஸை எல்லோருக்கும் தெரியும்படி வைக்க வேண்டும். FSSAI-இன் சொந்த இணையதளத்தில் (foscos.fssai.gov.in) அல்லது அதன் Food Safety Connect ஆப்பில் லைசென்ஸைச் சரிபார்க்கலாம் அல்லது புகார் செய்யலாம்.",
  "public.updated": "பக்கம் கடைசியாகப் புதுப்பிக்கப்பட்டது: {date}, {time}.",
  "public.footer": "ECCS · Eosfera Commercial Cleaning Services, ஹைதராபாத்",
  "public.none.title": "தற்போது காட்ட எதுவும் இல்லை",
  "public.none.gov": "ஒரு ரெஸ்டாரன்டின் FSSAI லைசென்ஸைச் சரிபார்க்க, FSSAI-இன் சொந்த இணையதளத்தை (foscos.fssai.gov.in) அல்லது அதன் Food Safety Connect ஆப்பைப் பயன்படுத்தவும்.",
  "public.down": "இந்தப் பக்கத்தை இப்போது திறக்க முடியவில்லை. ஒரு நிமிடம் கழித்து மீண்டும் முயற்சிக்கவும்.",
  "public.poster.scan": "உங்கள் போன் கேமராவால் ஸ்கேன் செய்யவும்",
