  "clock.assist.help": "ஓனர் அல்லது மேனேஜர் ஒருவருடைய வருகையை அல்லது புறப்பாட்டைப் பதிவு செய்யலாம். நபரைத் தேர்ந்தெடுக்கவும், பிறகு ஓனர் அல்லது மேனேஜர் தன் சொந்த PIN-ஐ டைப் செய்வார்.",
