  "face.enrolledHelp": "இவர் PIN ஸ்கிரீனில் கேமராவைப் பார்த்து தன் வருகையையும் புறப்பாட்டையும் பதிவு செய்கிறார்.",
  "face.notEnrolledHelp": "இவருடைய முகம் சேர்க்கப்படும் வரை, ஓனர் அல்லது மேனேஜர் தங்கள் PIN மூலம் இவருடைய வருகையையும் புறப்பாட்டையும் பதிவு செய்வார்கள்.",
  "face.declinedHelp": "இவர் ஒப்புக்கொள்ளவில்லை, அதில் தவறில்லை. ஓனர் அல்லது மேனேஜர் தங்கள் PIN மூலம் இவருடைய வருகையையும் புறப்பாட்டையும் பதிவு செய்வார்கள். இவருக்கு வேறு எதுவும் மாறாது.",
