  "face.ownerOnly": "ஓனர் மட்டுமே முகத்தைச் சேர்க்கவோ நீக்கவோ முடியும்.",
  "face.start": "இவருடைய முகத்தைச் சேர்",
  "face.again": "இவருடைய முகத்தை மீண்டும் எடு",
  "face.startHint": "முதலில் படித்து ஒப்புக்கொள்ள ஃபோனை {name} அவர்களிடம் கொடுங்கள்",
  "face.remove": "முகத்தை நீக்கு",
  "face.removeConfirm": "{name} அவர்களின் முகத்தை நீக்கவா? இவருடைய முக பேட்டர்ன் உடனே அழிக்கப்படும். அதன் பிறகு ஓனர் அல்லது மேனேஜர் இவருடைய வருகையையும் புறப்பாட்டையும் பதிவு செய்வார்கள்.",
  "face.removed": "முகம் நீக்கப்பட்டது",
  "face.later": "இதைப் பிறகு செய்",
  "face.consent.title": "வருகை, புறப்பாட்டைப் பதிவு செய்ய உங்கள் முகத்தைப் பயன்படுத்துதல்",
  "face.consent.for": "{name} அவர்கள் படித்துப் பதில் சொல்ல",
  "face.consent.intro": "இதை நீங்களே படியுங்கள், அல்லது யாரிடமாவது படித்துக் காட்டச் சொல்லுங்கள். முடிவு உங்களுடையது.",
  "face.consent.who": "{employer} உங்களுக்கு வேலை கொடுப்பவர் (முதலாளி), இதைக் கேட்பது அவர்தான். இந்த ஆப்பை நடத்தும் நிறுவனமான ECCS, {employer} சார்பாக இந்த டேட்டாவை வைத்திருக்கிறது.",
  "face.consent.why": "இது ஒரே ஒரு விஷயத்துக்கு மட்டுமே பயன்படுத்தப்படுகிறது: நீங்கள் வருகை, புறப்பாட்டைப் பதிவு செய்யும்போது அது நீங்கள்தான் என்று தெரிந்துகொள்ள. உங்கள் சம்பளம் அந்த நேரங்களை வைத்தே கணக்கிடப்படுகிறது.",
  "face.consent.not": "இது வேறு எதற்கும் பயன்படுத்தப்படுவதில்லை. இது விற்கப்படுவதில்லை, வேறு யாருக்கும் கொடுக்கப்படுவதில்லை, விளம்பரத்துக்குப் பயன்படுத்தப்படுவதில்லை.",
  "face.consent.choice": "நீங்கள் வேண்டாம் என்று சொல்லலாம். உங்கள் வேலையிலோ சம்பளத்திலோ எதுவும் மாறாது. அதற்குப் பதிலாக ஓனர் அல்லது மேனேஜர் உங்கள் வருகையையும் புறப்பாட்டையும் பதிவு செய்வார்கள்.",
  "face.consent.withdraw": "நீங்கள் எப்போது வேண்டுமானாலும் உங்கள் முடிவை மாற்றிக்கொள்ளலாம்: ஓனரிடம் சொல்லுங்கள், உங்கள் முக பேட்டர்ன் உடனே அழிக்கப்படும். நீங்கள் இந்த வேலையை விட்டுப் போகும்போதும் அது அழிக்கப்படும்.",
  "face.consent.ask": "உங்களுக்கு ஏதாவது கேள்வி இருந்தால், ஓனரிடம் கேளுங்கள்.",
  "face.consent.under18": "உங்கள் வயது 18-க்குக் குறைவாக இருந்தால், \"நான் ஒப்புக்கொள்ளவில்லை\" என்பதைத் தேர்ந்தெடுக்கவும்.",
  "face.consent.agree": "நான் ஒப்புக்கொள்கிறேன்",
