  "bde.quote.needsSignal": "சிக்னல் இல்லை. கொட்டேஷனுக்கு சிக்னல் தேவை: அதன் லிங்கை ECCS உருவாக்குகிறது. சிக்னல் இருக்கும்போது மீண்டும் முயற்சிக்கவும்.",
