  "bde.offline.thisLead": "இந்த லீட்",
  "offline.held.lead.gone": "இந்த லீட்டின் வேலையை ECCS ஏற்கவில்லை: இது வேறொருவருக்குக் கொடுக்கப்பட்டிருக்கலாம், அல்லது இதில் உள்ள ஏதோ ஒன்று மறுக்கப்பட்டிருக்கலாம். அது இன்னும் இந்த ஃபோனில் உள்ளது. ECCS ஆஃபீஸுக்கு ஃபோன் செய்யுங்கள்; பிறகு \"மீண்டும் அனுப்பு\" என்பதைத் தட்டவும். இந்த ஃபோனில் வைக்கப்பட்டவை: {count}",
  "offline.held.lead.finished": "இந்த லீட்டின் வேலையை ECCS ஏற்கவில்லை. அது இன்னும் இந்த ஃபோனில் உள்ளது. இந்த ஃபோனில் வைக்கப்பட்டவை: {count}",
  "offline.held.lead.cancelled": "இந்த லீட்டின் வேலையை ECCS ஏற்கவில்லை. அது இன்னும் இந்த ஃபோனில் உள்ளது. இந்த ஃபோனில் வைக்கப்பட்டவை: {count}",

  "buddy.name": "ECCS Buddy",
  "buddy.button": "Buddy",
  "buddy.buttonLabel": "ECCS Buddy-இடம் கேட்கவும்",
  "buddy.menu": "ECCS Buddy",
  "buddy.homeCard.title": "ECCS Buddy-இடம் கேட்கவும்",
  "buddy.homeCard.body": "சர்வீஸ் புக் செய்யலாம், செக் சேர்க்கலாம், SOP எழுதலாம், அல்லது எதையும் கேட்கலாம்.",
  "buddy.welcome.title": "வணக்கம், நான் ECCS Buddy",
  "buddy.welcome.body": "ஆப் அல்லது உங்கள் கிச்சன் பற்றி என்னிடம் கேளுங்கள்.",
  "buddy.welcome.more": "Buddy-ஆல் செய்ய முடிந்தவை",
  "buddy.welcome.can": "ஆப்பில் ஒன்றை எப்படிச் செய்வது என்பதற்கும், உணவுப் பாதுகாப்பு, சுத்தம், பூச்சிகள் மற்றும் கிச்சனை நடத்துவது பற்றிய கேள்விகளுக்கும் பதில் சொல்லும்.",
  "buddy.welcome.reads": "இன்றைய செக்லிஸ்ட்கள், விசிட்கள், உங்கள் ஸ்கோர், லைசென்ஸ்கள், இன்வாய்ஸ்கள், பிளான், புகார்கள், இன்ஸ்பெக்ஷன்கள், SOP-கள், லேபிள்கள் மற்றும் வெண்டர்களைப் பார்க்கும்.",
  "buddy.welcome.changes": "நீங்கள் தட்டி உறுதிப்படுத்துவதற்காகத் தயார் செய்யும்: சர்வீஸ் கோரிக்கையை புக் செய்வது அல்லது ரத்து செய்வது, செக்லிஸ்ட் ஐட்டங்கள் மற்றும் செக்லிஸ்ட்கள், SOP-கள், உணவு லேபிள்கள், ECCS-க்கான மெசேஜ்கள்.",
  "buddy.welcome.cannot": "ஒருபோதும் பணம் செலுத்தாது, உங்கள் பிளானை மாற்றாது, ஆவணங்களை அப்லோட் செய்யாது, ஸ்டாஃப் அட்டெண்டன்ஸ், சம்பளம் அல்லது முகங்களைப் பார்க்காது. அந்த ஸ்கிரீன்களை உங்களுக்காகத் திறக்கும்.",
  "buddy.welcome.ai": "பதில்களை AI எழுதுகிறது, அவை தவறாக இருக்கலாம். சாட்கள் {days} நாட்கள் வைக்கப்படும்.",
  "buddy.starters": "இப்படிக் கேட்டுப் பாருங்கள்",
  "buddy.starter.overdue": "இன்று {count} செக்லிஸ்ட்கள் நேரம் கடந்துவிட்டன: அவற்றைக் காட்டவும்",
  "buddy.starter.myDay": "இன்று இன்னும் என்ன செய்ய வேண்டியிருக்கிறது?",
  "buddy.starter.nextVisit": "என் அடுத்த ECCS விசிட் எப்போது?",
  "buddy.starter.addCheck": "ஒரு செக்லிஸ்ட் ஐட்டம் சேர்க்க வேண்டும்",
  "buddy.starter.newChecklist": "மதிய நேர செக்லிஸ்ட் ஒன்று சேர்க்க வேண்டும்",
