  "buddy.starter.findSop": "சுத்தம் செய்வதற்கு எங்களிடம் என்னென்ன SOP-கள் உள்ளன?",
  "buddy.starter.addLabel": "சாதத்துக்கு ஒரு லேபிள் சேமிக்க வேண்டும்",
