  "buddy.starter.licences": "எந்த லைசென்ஸ்களை ரினியூ செய்ய வேண்டும்?",
  "buddy.starter.howAddLicence": "லைசென்ஸை எப்படிச் சேர்ப்பது?",
  "buddy.starter.certificates": "என் பெஸ்ட் கன்ட்ரோல் சர்டிஃபிகேட் இன்னும் செல்லுபடியாகுமா?",
  "buddy.starter.whatsDue": "ECCS-க்கு நான் எவ்வளவு செலுத்த வேண்டும்?",
  "buddy.starter.howPay": "இன்வாய்ஸை எப்படிச் செலுத்துவது?",
  "buddy.starter.whatPlan": "என் பிளானில் என்னென்ன உள்ளன?",
  "buddy.starter.whyScore": "என் சுகாதார ஸ்கோர் ஏன் இப்படி இருக்கிறது?",
  "buddy.starter.raiseScore": "என் சுகாதார ஸ்கோரை எப்படி உயர்த்துவது?",
  "buddy.starter.fixFirst": "இன்ஸ்பெக்ஷனில் வந்தவற்றில் முதலில் எதைச் சரிசெய்ய வேண்டும்?",
  "buddy.starter.reportIssue": "கரப்பான் பூச்சியைப் பார்த்தேன், ECCS-இடம் தெரிவிக்கவும்",
  "buddy.starter.talkToEccs": "ECCS-இல் யாரிடமாவது பேச வேண்டும்",
  "buddy.starter.howAddStaff": "ஸ்டாஃப் ஒருவரை எப்படிச் சேர்ப்பது?",
  "buddy.starter.attendanceWhere": "இன்று யார் யார் வந்திருக்கிறார்கள் என்று எங்கே பார்ப்பது?",
  "buddy.starter.findVendor": "எங்களுக்கு அருகில் ஒரு காய்கறி சப்ளையரைத் தேடவும்",
