  "buddy.state.OFF": "Buddy இப்போது ஆஃபில் உள்ளது. ஆப்பின் ஸ்கிரீன்களிலிருந்தே எல்லாவற்றையும் செய்யலாம்:",
  "buddy.state.LIMIT": "Buddy இன்றைய வரம்பை எட்டிவிட்டது, நாளை மீண்டும் வரும். அதுவரை:",
  "buddy.state.PERSON_LIMIT": "இன்றைய {count} மெசேஜ்களையும் பயன்படுத்திவிட்டீர்கள். Buddy நாளை மீண்டும் வரும். அதுவரை:",
  "buddy.state.FAILED": "Buddy-ஆல் இப்போது பதில் அளிக்க முடியவில்லை. நீங்கள் டைப் செய்தது வைக்கப்பட்டுள்ளது: மீண்டும் முயற்சிக்கவும்.",
  "buddy.outOfScope": "உங்கள் ரெஸ்டாரன்ட் மற்றும் ECCS ஆப் தொடர்பானவற்றில் மட்டுமே என்னால் உதவ முடியும்.",
  "buddy.state.OUT_OF_SCOPE": "உங்கள் ரெஸ்டாரன்ட் மற்றும் ECCS ஆப் தொடர்பானவற்றில் மட்டுமே என்னால் உதவ முடியும். இவற்றில் ஒன்றை முயற்சிக்கவும்:",
  "buddy.state.TOO_FAST": "ஒரே நேரத்தில் நிறைய மெசேஜ்கள் வந்துள்ளன. ஒரு நிமிடம் காத்திருந்து, மீண்டும் அனுப்பவும்.",
  "buddy.state.CHAT_FULL": "இந்த சாட் நிறைந்துவிட்டது. தொடர, புதிய சாட்டைத் தொடங்கவும்.",
  "buddy.state.PAUSED": "Buddy-ஆல் உதவ முடியாத பல மெசேஜ்கள் வந்ததால், உங்களுக்கு நாளை வரை Buddy நிறுத்தி வைக்கப்பட்டுள்ளது. ஆப்பின் ஸ்கிரீன்களிலிருந்தே எல்லாவற்றையும் செய்யலாம்:",
  "buddy.input.counter": "{max}-இல் {count} எழுத்துகள்",
  "buddy.offline": "Buddy-க்கு இன்டர்நெட் தேவை. நீங்கள் டைப் செய்தது வைக்கப்பட்டுள்ளது: சிக்னல் வந்ததும் அனுப்பவும்.",
  "buddy.error.BUDDY_NOT_ALLOWED": "ECCS Buddy ரெஸ்டாரன்ட்டின் ஓனருக்கும் மேனேஜருக்கும் மட்டுமே.",
  "buddy.error.BUDDY_CARD_USED": "இந்த கார்டு ஏற்கனவே பயன்படுத்தப்பட்டுவிட்டது.",
  "buddy.error.BUDDY_CARD_EXPIRED": "இந்த கார்டின் நேரம் முடிந்துவிட்டது. Buddy-இடம் மீண்டும் கேளுங்கள்.",
