  "buddy.mic.stop": "நிறுத்து",
  "buddy.mic.listening": "கேட்கிறது… இப்போது பேசுங்கள்",
  "buddy.mic.language": "பேசும் மொழி: {language}",
  "buddy.mic.chooseLanguage": "நீங்கள் பேசப்போகும் மொழி",
  "buddy.mic.expoGo": "பேச, உங்கள் கீபோர்டில் உள்ள மைக்ரோஃபோனைப் பயன்படுத்தவும். Buddy-இன் சொந்த மைக், இன்ஸ்டால் செய்யப்பட்ட ECCS ஆப்பில் வேலை செய்யும்.",
  "buddy.mic.unavailable": "இந்த ஃபோனில் பேசும் வசதி இல்லை. உங்கள் கீபோர்டில் உள்ள மைக்ரோஃபோனைப் பயன்படுத்தவும்.",
  "buddy.mic.askTitle": "மைக்ரோஃபோனைப் பயன்படுத்தவா?",
  "buddy.mic.askBody": "நீங்கள் சொல்வதை Buddy பெட்டியில் எழுத்துகளாக மாற்றும்; அனுப்பும் முன் நீங்கள் சரிபார்க்கலாம். அனுப்பு என்பதைத் தட்டும் வரை எதுவும் அனுப்பப்படாது.",
  "buddy.mic.askYes": "மைக்ரோஃபோனை அனுமதிக்கவும்",
  "buddy.mic.denied": "ECCS-க்கு மைக்ரோஃபோன் அனுமதி இல்லை. பேச, ஃபோனின் செட்டிங்ஸில் அனுமதிக்கவும்: ஆப்ஸ், ECCS, அனுமதிகள், மைக்ரோஃபோன்.",
  "buddy.mic.openSettings": "செட்டிங்ஸைத் திறக்கவும்",
